import{_t as e,it as t,n,rt as r}from"./chunks/framework.rZZZX73S.js";var i=JSON.parse(`{"title":"UPnPumpkin plugin API","description":"","frontmatter":{"editLink":"https://github.com/filiphsps/pumpkin-plugins/edit/master/tools/upnpumpkin-api/docs/index.md"},"headers":[],"relativePath":"tools/upnpumpkin-api/docs/index.md","filePath":"tools/upnpumpkin-api/docs/index.md","lastUpdated":1791428389000}`),a={name:`tools/upnpumpkin-api/docs/index.md`};function o(n,i,a,o,s,c){return e(),r(`div`,null,[...i[0]||=[t(`<h1 id="upnpumpkin-plugin-api" tabindex="-1">UPnPumpkin plugin API <a class="header-anchor" href="#upnpumpkin-plugin-api" aria-label="Permalink to “UPnPumpkin plugin API”">​</a></h1><p><code>@pumpkin-plugins/upnpumpkin-api</code> lets one plugin request a leased port mapping from UPnPumpkin through Pumpkin plugin messages. It contains the message protocol, client, watcher, and helper for turning a successful mapping into a public URL.</p><h2 id="watch-a-mapping" tabindex="-1">Watch a mapping <a class="header-anchor" href="#watch-a-mapping" aria-label="Permalink to “Watch a mapping”">​</a></h2><p>Create a <code>PortMapClient</code> with the plugin message sender, then create a <code>MappingWatcher</code> with a stable key, protocol, internal port, and description. Start the watcher after the plugin loads, call <code>tick()</code> from the plugin&#39;s task handler, and call <code>stop()</code> when unloading or when the web service no longer needs the port.</p><p>The watcher requests a mapping immediately and refreshes it while running. <code>openUrl</code> returns a URL only when the reported state contains a usable public address. When UPnPumpkin is not installed or has not loaded yet, the watcher reports an unavailable state; callers should handle it without blocking their own service from starting.</p><p>Unused requests expire after five minutes. UPnPumpkin also applies a per-plugin mapping limit, so stop watchers promptly. The API package does not perform router discovery itself; the server-side plugin owns that network work.</p>`,6)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};